"""Render the saved current preprocessor profile as a standalone interactive report."""
import json,pathlib
r=json.loads(pathlib.Path('suite/reports/c-preprocessor-current-profile-20261015.json').read_text())
data={}
for app,d in r['applications'].items():
 s=d['stack'];data[app]={'files':d['timing_summary']['files'],'ms':d['timing_summary']['median_ms'],'samples':s['samples'],'phases':s['exclusive_phase_percent'],'copy':s['category_percent']['memmove'],'copyExpand':s['memmove_context_percent']['Macro expansion'],'alloc':s['category_percent']['allocator'],'utf8':s['utf8_validation_percent']}
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{margin:0;color:var(--foreground,#25262b);font:14px/1.5 var(--font-sans,system-ui);background:transparent}h2{font-size:21px;letter-spacing:-.4px;margin:0 0 6px}p{margin:0 0 14px}.muted,small{color:var(--muted-foreground,#777)}.apps{display:flex;gap:8px;margin:16px 0}.apps button{flex:1;padding:10px 6px;border:1px solid var(--border,#ddd);background:transparent;color:inherit;border-radius:8px;cursor:pointer;font:inherit}.apps button[aria-pressed=true]{border-color:var(--accent,#7376e7);background:var(--accent-surface,#f0efff)}strong{font-weight:650}.row{display:grid;grid-template-columns:minmax(145px,1fr) 2fr 46px;gap:12px;align-items:center;margin:10px 0}.track{height:12px;background:var(--muted,#eee);border-radius:3px;overflow:hidden}.bar{height:100%;background:var(--chart-1,#6574d9)}.pct{text-align:right;font-variant-numeric:tabular-nums}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:20px 0 10px}.stat{border:1px solid var(--border,#ddd);padding:12px;border-radius:8px}.value{font-size:22px;line-height:1.3;font-weight:650}.notes{border-top:1px solid var(--border,#ddd);margin-top:20px;padding-top:16px}.notes p{margin-bottom:10px}h3{font-size:15px;margin:0 0 10px}@media(max-width:430px){.row{grid-template-columns:minmax(120px,1.1fr) 1fr 42px;gap:6px;font-size:12px}.value{font-size:19px}.stat{padding:8px}.apps button{font-size:12px}}
</style></head><body><h2>Current preprocessor profile</h2><p class="muted">Lua, QuickJS, SQLite · 44 translation units · Apple M5 Max</p><div class="apps" id="tabs"></div><p id="timing"></p><h3>Share of sampled time by operation</h3><div id="bars"></div><small>Exclusive attribution to the nearest recognizable operation. Output includes flush overhead; optimized inlining limits attribution.</small><div class="stats"><div class="stat"><div id="copies" class="value"></div>Memory copying</div><div class="stat"><div id="alloc" class="value"></div>Allocator activity</div><div class="stat"><div id="utf8" class="value"></div>UTF-8 validation</div></div><p id="copyNote" class="muted"></p><div class="notes"><h3>What the profile points to next</h3><p><strong>Reduce token movement during expansion.</strong> Copying inside expansion consumes 7.6–16.4% of all samples. The in-place token-stream splice is a candidate; these stacks do not isolate its exact contribution.</p><p><strong>Streamline scanning.</strong> Token scanning still consumes 25–36%. Character classification and physical-location tracking are the next paths to inspect.</p><p><strong>Avoid repeated header resolution.</strong> Search plus canonicalization consumes 8–18%. Cache resolved paths using the including directory and include-next origin as part of the key.</p><p class="muted">The last UTF-8 change worked: validation fell from 4–5% in the prior Lua/SQLite survey to below 0.6%. Allocator activity is now about 5–7%, so moving every remaining allocation into an arena is a lower priority.</p></div><small>Method: seven serial timing rounds after warmup; separate six-second stack samples at a requested 1 ms interval per application. Warm filesystem caches; source/token caches reset for each translation unit. Timing excludes raw top-level reads and returned-output destruction. Copying, allocator, and UTF-8 shares overlap with operation shares. Changes in percentages alone are not speedups.</small><script>
const data=DATA;const names={lua:'Lua',quickjs:'QuickJS',sqlite:'SQLite'};const tabs=document.getElementById('tabs');for(const [key,d]of Object.entries(data)){const b=document.createElement('button');b.textContent=names[key];b.dataset.app=key;b.onclick=()=>show(key);tabs.appendChild(b)}function show(key){const d=data[key];for(const b of tabs.children)b.setAttribute('aria-pressed',b.dataset.app===key);document.getElementById('timing').innerHTML='<strong>'+d.ms.toFixed(1)+' ms</strong> median per whole application · '+d.files+' files · '+d.samples.toLocaleString()+' samples';const bars=document.getElementById('bars');bars.innerHTML='';for(const[label,value]of Object.entries(d.phases)){const row=document.createElement('div');row.className='row';row.innerHTML='<span>'+label+'</span><div class="track"><div class="bar" style="width:'+value+'%"></div></div><span class="pct">'+value.toFixed(1)+'%</span>';bars.appendChild(row)}for(const[id,value]of [['copies',d.copy],['alloc',d.alloc],['utf8',d.utf8]])document.getElementById(id).textContent=value.toFixed(1)+'%';document.getElementById('copyNote').textContent=d.copyExpand.toFixed(1)+'% of all samples are memory copying inside macro expansion.'}show('quickjs');console.log('Validated '+Object.keys(data).length+' workloads; phase totals',Object.values(data).map(d=>Object.values(d.phases).reduce((a,b)=>a+b,0)));
</script></body></html>'''.replace('DATA',json.dumps(data))
p=pathlib.Path('suite/reports/c-preprocessor-current-profile-20261015.html');p.write_text(html)
